sys_script.script:
(function executeRule(current, previous /*null when async*/) {
    // When status changes to 'approved', update leave balance
    var newStatus = current.getValue('status');
    var oldStatus = previous.getValue('status');

    if (newStatus == 'approved' && oldStatus != 'approved') {
        var employeeId = current.getValue('employee');
        var leaveType = current.getValue('leave_type');
        var numberOfDays = parseInt(current.getValue('number_of_days'), 10);

        // Find the leave balance record for this employee and leave type
        var balanceGr = new GlideRecord('x_2073292_leave_0_leave_balance');
        balanceGr.addQuery('employee', employeeId);
        balanceGr.addQuery('leave_type', leaveType);
        balanceGr.query();

        if (balanceGr.next()) {
            var currentRemaining = parseInt(balanceGr.getValue('remaining'), 10);

            // If remaining would go below 0 and leave_type is NOT work_from_home, abort
            if ((currentRemaining - numberOfDays) < 0 && leaveType != 'work_from_home') {
                gs.addErrorMessage('Insufficient leave balance. Remaining: ' + currentRemaining + ' days');
                current.setAbortAction(true);
                return;
            }

            // Update the balance
            var currentUsed = parseInt(balanceGr.getValue('used'), 10);
            balanceGr.setValue('used', currentUsed + numberOfDays);
            balanceGr.setValue('remaining', currentRemaining - numberOfDays);
            balanceGr.update();
        }

        // Set approval details
        current.setValue('approved_by', gs.getUserID());
        current.setValue('approval_date', new GlideDateTime());
    }
})(current, previous);
